import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs"
import path from "node:path"

const root = process.cwd()
const migrationsDir = path.join(root, "supabase", "migrations")
const outputDir = path.join(root, "supabase", "sql-editor")
const outputFile = path.join(outputDir, "01_all_migrations.sql")
const resumeFile = path.join(outputDir, "01_resume_from_0003.sql")
const migrations = readdirSync(migrationsDir).filter((file) => /^\d{4}_.+\.sql$/.test(file)).sort()

if (migrations.length === 0) throw new Error("No migrations found")

const sections = migrations.map((file) => {
  const sql = readFileSync(path.join(migrationsDir, file), "utf8").trim()
  if (!/^begin;/i.test(sql) || !/commit;$/i.test(sql)) throw new Error(`${file} must be transaction wrapped`)
  return `-- ============================================================================\n-- ${file}\n-- ============================================================================\n${sql}`
})

const header = `-- Lumina Jasa - complete schema for Supabase SQL Editor
-- Generated by: node scripts/build-sql-editor-bundle.mjs
-- Source of truth: supabase/migrations/*.sql
--
-- IMPORTANT:
-- 1. Run this only on a fresh Supabase project.
-- 2. Run the whole file, in order, before 02_demo_seed.sql.
-- 3. Do not rerun it after tables have been created; use versioned migrations instead.
`

mkdirSync(outputDir, { recursive: true })
writeFileSync(outputFile, `${header}\n${sections.join("\n\n")}\n`, "utf8")
const resumeHeader = `-- Lumina Jasa - recovery after the spatial_ref_sys failure in 0003_rls.sql
-- Use this only when 0001 and 0002 succeeded and 0003 failed with SQLSTATE 42501.
-- It installs the corrected 0003 migration and continues through 0010.
`
writeFileSync(resumeFile, `${resumeHeader}\n${sections.slice(2).join("\n\n")}\n`, "utf8")
console.log(`Wrote ${path.relative(root, outputFile)} from ${migrations.length} migrations.`)
console.log(`Wrote ${path.relative(root, resumeFile)} from migrations 0003-${migrations.at(-1).slice(0, 4)}.`)
